<!-- Generated by `npx @musikhood-dev/auth-client init` — this file is yours, edit freely. -->
<script setup lang="ts">
import { computed, ref } from 'vue'
import { useAuth, useMfa } from '@musikhood-dev/auth-client/vue'

import MfaCodeForm, { type MfaCodeSubmit } from '@@/components/auth/MfaCodeForm.vue'
import { Button } from '@@/components/ui/button'
import { Input } from '@@/components/ui/input'
import { Label } from '@@/components/ui/label'
import { isAuthError, loginErrorMessage, MFA_TEXTS, mfaErrorMessage } from '@@/lib/mfa'

// Login form with the 2FA code step. Render it inside <AuthBoundary mode="guest"> — after
// a successful login the package redirects to `homePath` by itself.
const { login } = useAuth()
const { stage, verify, reset } = useMfa()

const username = ref('')
const password = ref('')
// Inline message under the password form (bad password, 429 limit, expired 2FA step).
const formError = ref<string | null>(null)
const mfaError = ref<string | null>(null)

const loggingIn = computed(() => login.isPending.value)
const verifying = computed(() => verify.isPending.value)

async function handleLogin() {
  formError.value = null
  mfaError.value = null
  try {
    await login({ username: username.value, password: password.value })
  } catch (error) {
    // 401 mfa_required → stage === 'code': the code step renders by itself.
    if (isAuthError(error, 'MfaRequiredError')) return
    if (isAuthError(error, 'MfaEnrollmentRequiredError')) {
      // The panel requires 2FA and the user has none: full navigation to the setup page.
      if (error.enrollmentUrl) window.location.assign(error.enrollmentUrl)
      else formError.value = MFA_TEXTS.enrollmentFailed
      return
    }
    formError.value = loginErrorMessage(error)
  }
}

async function handleMfaSubmit(data: MfaCodeSubmit) {
  mfaError.value = null
  try {
    await verify(data)
  } catch (error) {
    if (isAuthError(error, 'MfaTokenExpiredError')) {
      // auth-client already returned to the password step (stage idle).
      formError.value = MFA_TEXTS.tokenExpired
      return
    }
    mfaError.value = mfaErrorMessage(error) ?? MFA_TEXTS.verifyFailed
  }
}

function backToPassword() {
  mfaError.value = null
  reset()
}
</script>

<template>
  <div v-if="stage === 'code'" class="grid gap-4">
    <p class="text-sm text-muted-foreground">Wpisz kod weryfikacji dwuetapowej</p>
    <MfaCodeForm
      :is-pending="verifying"
      :error="mfaError"
      submit-label="Zweryfikuj"
      cancel-label="Wróć do logowania"
      @submit="handleMfaSubmit"
      @cancel="backToPassword"
    />
  </div>
  <form v-else class="grid gap-4" @submit.prevent="handleLogin">
    <div class="grid gap-1.5">
      <Label for="login-username">Email</Label>
      <Input id="login-username" v-model="username" type="email" autocomplete="username" required />
    </div>
    <div class="grid gap-1.5">
      <Label for="login-password">Hasło</Label>
      <Input
        id="login-password"
        v-model="password"
        type="password"
        autocomplete="current-password"
        required
      />
    </div>
    <p v-if="formError" role="alert" class="text-sm text-destructive">{{ formError }}</p>
    <Button type="submit" class="w-full" :disabled="loggingIn">
      {{ loggingIn ? 'Logowanie…' : 'Zaloguj się' }}
    </Button>
  </form>
</template>
